1	package server
2	
3	import (
4		"math"
5		"net/http"
6		"sort"
7		"sync"
8	)
9	
10	// deviceInput is one member of a create-pool request.
11	type deviceInput struct {
12		ID            string `json:"id"`
13		CapacityBytes int64  `json:"capacityBytes"`
14		FaultDomain   string `json:"faultDomain"`
15	}
16	
17	type createPoolInput struct {
18		ID      string        `json:"id"`
19		Devices []deviceInput `json:"devices"`
20	}
21	
22	type reservationInput struct {
23		RequestID string `json:"requestId"`
24		Bytes     int64  `json:"bytes"`
25	}
26	
27	// deviceView is the public representation of a pool device.
28	type deviceView struct {
29		ID            string `json:"id"`
30		CapacityBytes int64  `json:"capacityBytes"`
31		FaultDomain   string `json:"faultDomain"`
32	}
33	
34	// poolView is the public representation of a storage pool.
35	type poolView struct {
36		ID               string       `json:"id"`
37		Devices          []deviceView `json:"devices"`
38		RawCapacityBytes int64        `json:"rawCapacityBytes"`
39		AllocatedBytes   int64        `json:"allocatedBytes"`
40		AvailableBytes   int64        `json:"availableBytes"`
41	}
42	
43	// reservationView is the result of a successful reservation request.
44	type reservationView struct {
45		PoolID    string `json:"poolId"`
46		RequestID string `json:"requestId"`
47		Bytes     int64  `json:"bytes"`
48	}
49	
50	type reservation struct {
51		requestID string
52		bytes     int64
53	}
54	
55	type pool struct {
56		id           string
57		devices      []deviceInput
58		rawCapacity  int64
59		reservations map[string]reservation
60	}
61	
62	func (p *pool) allocated() int64 {
63		var total int64
64		for _, r := range p.reservations {
65			total += r.bytes
66		}
67		return total
68	}
69	
70	func (p *pool) view() poolView {
71		devices := make([]deviceView, len(p.devices))
72		for i, d := range p.devices {
73			devices[i] = deviceView{ID: d.ID, CapacityBytes: d.CapacityBytes, FaultDomain: d.FaultDomain}
74		}
75		allocated := p.allocated()
76		return poolView{
77			ID:               p.id,
78			Devices:          devices,
79			RawCapacityBytes: p.rawCapacity,
80			AllocatedBytes:   allocated,
81			AvailableBytes:   p.rawCapacity - allocated,
82		}
83	}
84	
85	// store is the in-memory state of the service. It is wiped on restart.
86	type store struct {
87		mu          sync.RWMutex
88		pools       map[string]*pool
89		deviceOwner map[string]string
90	}
91	
92	func newStore() *store {
93		return &store{
94			pools:       make(map[string]*pool),
95			deviceOwner: make(map[string]string),
96		}
97	}
98	
99	func validID(id string) bool {
100		return idPattern.MatchString(id)
101	}
102	
103	func (s *store) listPools(w http.ResponseWriter) {
104		s.mu.RLock()
105		ids := make([]string, 0, len(s.pools))
106		for id := range s.pools {
107			ids = append(ids, id)
108		}
109		sort.Strings(ids)
110		items := make([]poolView, 0, len(ids))
111		for _, id := range ids {
112			items = append(items, s.pools[id].view())
113		}
114		s.mu.RUnlock()
115		writeJSON(w, http.StatusOK, map[string]any{"items": items})
116	}
117	
118	func (s *store) getPool(w http.ResponseWriter, id string) {
119		if !validID(id) {
120			writeError(w, http.StatusBadRequest, "invalid_request")
121			return
122		}
123		s.mu.RLock()
124		p, ok := s.pools[id]
125		var v poolView
126		if ok {
127			v = p.view()
128		}
129		s.mu.RUnlock()
130		if !ok {
131			writeError(w, http.StatusNotFound, "pool_not_found")
132			return
133		}
134		writeJSON(w, http.StatusOK, v)
135	}
136	
137	func (s *store) createPool(w http.ResponseWriter, r *http.Request) {
138		var in createPoolInput
139		if !decodeRequest(r, &in) {
140			writeError(w, http.StatusBadRequest, "invalid_request")
141			return
142		}
143		// Validate the whole payload before touching any state so a failure
144		// never leaves a partial pool behind.
145		if !validID(in.ID) || len(in.Devices) == 0 {
146			writeError(w, http.StatusBadRequest, "invalid_request")
147			return
148		}
149		seen := make(map[string]bool, len(in.Devices))
150		var rawCapacity int64
151		for _, d := range in.Devices {
152			if !validID(d.ID) || d.CapacityBytes <= 0 || d.FaultDomain == "" || seen[d.ID] {
153				writeError(w, http.StatusBadRequest, "invalid_request")
154				return
155			}
156			if rawCapacity > math.MaxInt64-d.CapacityBytes {
157				writeError(w, http.StatusBadRequest, "invalid_request")
158				return
159			}
160			seen[d.ID] = true
161			rawCapacity += d.CapacityBytes
162		}
163	
164		s.mu.Lock()
165		defer s.mu.Unlock()
166		if _, ok := s.pools[in.ID]; ok {
167			writeError(w, http.StatusConflict, "pool_exists")
168			return
169		}
170		for _, d := range in.Devices {
171			if _, busy := s.deviceOwner[d.ID]; busy {
172				writeError(w, http.StatusConflict, "device_in_use")
173				return
174			}
175		}
176	
177		devices := append([]deviceInput(nil), in.Devices...)
178		p := &pool{
179			id:           in.ID,
180			devices:      devices,
181			rawCapacity:  rawCapacity,
182			reservations: make(map[string]reservation),
183		}
184		s.pools[in.ID] = p
185		for _, d := range devices {
186			s.deviceOwner[d.ID] = in.ID
187		}
188		writeJSON(w, http.StatusCreated, p.view())
189	}
190	
191	func (s *store) deletePool(w http.ResponseWriter, id string) {
192		if !validID(id) {
193			writeError(w, http.StatusBadRequest, "invalid_request")
194			return
195		}
196		s.mu.Lock()
197		defer s.mu.Unlock()
198		p, ok := s.pools[id]
199		if !ok {
200			writeError(w, http.StatusNotFound, "pool_not_found")
201			return
202		}
203		if len(p.reservations) > 0 {
204			writeError(w, http.StatusConflict, "pool_not_empty")
205			return
206		}
207		for _, d := range p.devices {
208			delete(s.deviceOwner, d.ID)
209		}
210		delete(s.pools, id)
211		w.WriteHeader(http.StatusNoContent)
212	}
213	
214	func (s *store) createReservation(w http.ResponseWriter, r *http.Request, poolID string) {
215		var in reservationInput
216		if !decodeRequest(r, &in) {
217			writeError(w, http.StatusBadRequest, "invalid_request")
218			return
219		}
220		if !validID(poolID) || !validID(in.RequestID) || in.Bytes <= 0 {
221			writeError(w, http.StatusBadRequest, "invalid_request")
222			return
223		}
224	
225		s.mu.Lock()
226		defer s.mu.Unlock()
227		p, ok := s.pools[poolID]
228		if !ok {
229			writeError(w, http.StatusNotFound, "pool_not_found")
230			return
231		}
232		if existing, dup := p.reservations[in.RequestID]; dup {
233			if existing.bytes != in.Bytes {
234				writeError(w, http.StatusConflict, "idempotency_conflict")
235				return
236			}
237			writeJSON(w, http.StatusOK, reservationView{PoolID: poolID, RequestID: existing.requestID, Bytes: existing.bytes})
238			return
239		}
240		allocated := p.allocated()
241		if allocated > p.rawCapacity-in.Bytes {
242			writeError(w, http.StatusConflict, "insufficient_capacity")
243			return
244		}
245		p.reservations[in.RequestID] = reservation{requestID: in.RequestID, bytes: in.Bytes}
246		writeJSON(w, http.StatusCreated, reservationView{PoolID: poolID, RequestID: in.RequestID, Bytes: in.Bytes})
247	}
248	
249	func (s *store) deleteReservation(w http.ResponseWriter, poolID, requestID string) {
250		if !validID(poolID) || !validID(requestID) {
251			writeError(w, http.StatusBadRequest, "invalid_request")
252			return
253		}
254		s.mu.Lock()
255		defer s.mu.Unlock()
256		p, ok := s.pools[poolID]
257		if !ok {
258			writeError(w, http.StatusNotFound, "pool_not_found")
259			return
260		}
261		// Deleting an unknown or already-deleted reservation is a success.
262		delete(p.reservations, requestID)
263		w.WriteHeader(http.StatusNoContent)
264	}
